/**
 * The automation sub-type tables (Phase 1). An automation is a COMPOSITE: one
 * `elementum_automation` + one `elementum_workflow_publish` + one trigger block
 * + N task blocks, each trigger/task kind its own terraform resource type. This
 * is the automation analogue of `entities/agent-tool/types.ts`: per-sub-type
 * knowledge is one ROW, and only *implemented* kinds round-trip.
 *
 * Phase 1 implements the `onDemand` trigger and the `executeScript` +
 * `setVariable` (create form) tasks end to end. Every other kind is DECLARED so
 * the pull partition REPORTS it by name (plan §6) instead of "unknown resource",
 * and adoption/build-vs-export scope ONLY the implemented resource types — an adopted
 * kind the printer can't reconstruct would plan as a destroy on rebuild.
 *
 * `typeKey` is the wire discriminant the authoring builders emit
 * (`triggers.ts` trigger `wire` keys, `tasks.ts` `ActionDef.key`); `resourceType`
 * is the terraform type ei's export uses. Only the implemented rows' `typeKey`
 * is load-bearing (to-tf maps authored → resource by it); the declared rows
 * need only an accurate `resourceType` for from-tf recognition.
 */
export interface AutomationSubType {
    /** Wire discriminant: a trigger `wire` key or a `ActionDef.key`. */
    readonly typeKey: string;
    /** Terraform resource type, e.g. "elementum_on_demand_trigger". */
    readonly resourceType: string;
    /** Round-trips on the terraform path (to-tf + from-tf + printer). */
    readonly implemented?: true;
}
/** The automation's own resource + its versioning/publish resource. */
export declare const AUTOMATION_RESOURCE_TYPE = "elementum_automation";
export declare const WORKFLOW_PUBLISH_RESOURCE_TYPE = "elementum_workflow_publish";
export declare const TABLE_RECORDS_SEARCH_TASK_RESOURCE_TYPE = "elementum_table_records_search_task";
/** Trigger kinds. One trigger per automation. Phase 1: onDemand only. */
export declare const TRIGGER_SUB_TYPES: readonly AutomationSubType[];
/**
 * Task kinds. All rows are implemented as of `aiFileAnalysis` (the last
 * holdout — it needs its `elementum_ai_file_reader` target to also round-trip,
 * see `entities/file-reader/types.ts`). `variable` (setVariable's create
 * form) is the one worth calling out: the tf dialect carries ONE variable per
 * task as variable_name/variable_type/value, and the provider's variable_id
 * is COMPUTED, so the compose-path client UUID never reaches HCL. A future
 * new task kind lands here declared-only first (see the doc comment on
 * {@link ALL_AUTOMATION_TASK_TYPE_SET} below) until its row flips implemented.
 */
export declare const TASK_SUB_TYPES: readonly AutomationSubType[];
export declare const BRANCH_SUB_TYPES: readonly AutomationSubType[];
export declare const ALL_AUTOMATION_SUB_TYPES: readonly AutomationSubType[];
export declare const AUTOMATION_SUB_TYPE_BY_TYPE_KEY: ReadonlyMap<string, AutomationSubType>;
export declare const AUTOMATION_SUB_TYPE_BY_RESOURCE: ReadonlyMap<string, AutomationSubType>;
/** Trigger/task resource types the terraform path round-trips today. */
export declare const IMPLEMENTED_TRIGGER_RESOURCE_TYPES: readonly string[];
export declare const IMPLEMENTED_TASK_RESOURCE_TYPES: readonly string[];
/**
 * The resource types adoption/build-vs-export scope for automations: the automation +
 * workflow_publish skeleton plus the implemented trigger/task kinds. Composite,
 * so the whole set moves together.
 */
export declare const IMPLEMENTED_AUTOMATION_RESOURCE_TYPES: readonly string[];
/** Every declared automation-family resource type — the partition recognizes these by name. */
export declare const ALL_AUTOMATION_RESOURCE_TYPES: readonly string[];
export declare const AUTOMATION_RESOURCE_TYPES: readonly string[];
export declare const AUTOMATION_TRIGGER_TYPES: readonly string[];
export declare const AUTOMATION_TASK_TYPES: readonly string[];
export declare const AUTOMATION_BRANCH_TYPES: string[];
export declare const AUTOMATION_TRIGGER_TYPE_SET: ReadonlySet<string>;
export declare const AUTOMATION_TASK_TYPE_SET: ReadonlySet<string>;
/**
 * Every DECLARED task resource type, implemented or not — for from-tf's graph
 * walk (which task blocks belong to this automation's tree) and its
 * dependency-recognition checks. Deliberately broader than
 * {@link AUTOMATION_TASK_TYPE_SET} (implemented-only, the adoption/build-vs-export
 * scope): a declared-but-unimplemented type (none currently declared — a
 * future new task kind lands here first, before its row flips implemented)
 * must still be walked into the task graph so from-tf's own dedicated
 * diagnostic for it fires, rather than the block silently falling out of the
 * graph and surfacing as an unrelated "unresolved parent"/"orphaned task"
 * error.
 */
export declare const ALL_AUTOMATION_TASK_TYPE_SET: ReadonlySet<string>;
export declare const AUTOMATION_BRANCH_TYPE_SET: ReadonlySet<string>;
